 async function ticket(id){if(!me){location.hash='login';return}const r=await api('/support/tickets/'+e(id)),v=r.ticket;app.innerHTML=`<section class="page ops-case"><a href="/#support-tickets" class="text-link">← ${t('Murojaatlar','Обращения','Requests')}</a>${pageTitle(s(v.subject),'#'+s(v.id),`<span class="ux-chip">${stateLabel(v.status)}</span>`)}${v.order_id?`<a class="button-secondary" href="/#order/${e(v.order_id)}">${t('Buyurtmani ochish','Открыть заказ','Open order')}</a>`:''}<div class="panel ops-case-thread">${r.entries.map(m=>`<article><header><b>${m.is_support?t('Yordam jamoasi','Поддержка','Support team'):t('Foydalanuvchi','Пользователь','Customer')}</b><time>${parseServerDate(m.created_at).toLocaleString(localeTag())}</time></header><p data-user-content>${s(m.body)}</p></article>`).join('')}<form id="ops-ticket-reply"><div class="field"><label>${t('Javob','Ответ','Reply')}</label><textarea name="body" minlength="2" maxlength="5000" required></textarea></div><div class="field"><label>${t('Holat','Статус','Status')}</label><select name="status"><option value="${r.can_manage?'waiting_customer':'open'}">${r.can_manage?t('Foydalanuvchi javobini kutish','Ожидать ответа пользователя','Await customer reply'):t('Javob so‘rash / qayta ochish','Запросить ответ / открыть снова','Request a reply / reopen')}</option>${r.can_manage?`<option value="open">${t('Ko‘rib chiqishni davom ettirish','Продолжить рассмотрение','Keep open')}</option>`:''}<option value="resolved">${t('Yakunlash','Завершить','Resolve')}</option></select></div><button class="button-primary">${t('Javob yuborish','Отправить ответ','Send reply')}</button></form></div></section>`;bind($('#ops-ticket-reply'),async d=>{await api('/support/tickets/'+e(id),{method:'POST',body:JSON.stringify(d)});await ticket(id)})}
